pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple token that tracks transferFrom calls
        SimpleToken token = new SimpleToken();
        address from = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        uint256 amount = 100;

        // Call transfer on the contract
        c.transfer(from, address(token), tos, amount);

        // The reference C calls transferFrom on the token, so token.balanceOf(from) decreases
        // The buggy C calls transfer on the token, which does nothing (no transferFrom)
        // Token's balanceOf(from) remains unchanged (100) in buggy version
        // For the test to pass on reference and fail on buggy, we assert that balanceOf(from) decreased
        // Since we started with from having 0, reference would revert? Actually token has no balance
        // Let's adjust: give from some tokens first
        token.mint(from, amount);
        // Reset and call again
        c = new C();
        c.transfer(from, address(token), tos, amount);
        // Reference: token.transferFrom called, from balance = 0
        // Buggy: token.transfer called, does nothing, from balance = 100
        assertTrue(token.balanceOf(from) == 0);
    }
}

contract SimpleToken {
    mapping(address => uint256) public balanceOf;
    function mint(address to, uint256 amount) public { balanceOf[to] += amount; }
    function transferFrom(address, address, uint256) public returns (bool) {
        // In reference, this is called; in buggy, transfer is called instead
        return true;
    }
    function transfer(address, uint256) public returns (bool) { return true; }
}

