pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a token contract that tracks which function was called
        // through a public counter
        TokenMock token = new TokenMock();
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);
        c.transfer(address(this), address(token), tos, 100);
        // The reference calls transferFrom, which sets callType to 1;
        // the bug calls transfer, which sets callType to 2.
        // The test asserts that the callType is 1 (reference behavior).
        // The buggy version will have callType = 2, so the assert fails.
        assertTrue(token.callType() == 1);
    }
}

contract TokenMock {
    uint256 public callType; // 0 = none, 1 = transferFrom, 2 = transfer
    function transferFrom(address, address, uint256) external returns (bool) {
        callType = 1;
        return true;
    }
    function transfer(address, uint256) external returns (bool) {
        callType = 2;
        return true;
    }
}

