import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Concrete scenario: call transfer with an empty _tos array
        address from = address(0x123);
        address caddress = address(0x456);
        address[] memory tos = new address[](0);
        uint v = 100;

        bool ok;
        try c.transfer(from, caddress, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert that the call reverts (ok == false) — reference reverts, bug does not
        assertTrue(ok == false);
    }
}

// Explanation: In the reference P, the require(_tos.length > 0) causes a revert
// when the array is empty. In the buggy M, that require is deleted, so the loop
// runs zero iterations and the function returns true without reverting.
// Thus calling transfer with empty _tos makes P revert and M succeed.
// Our assertion that ok == false will pass for correct C and fail for buggy C.

