pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a scenario where a state change can be observed
        address from = address(0x123);
        address to = address(0x456);
        // Deploy a token mock that will revert on transferFrom (to isolate the require check)
        // But we only need the call to succeed for the buggy version to show a state difference.
        // Use a simple account that executes no code (address(0)) - the call will succeed (no code) and do nothing.
        // We'll use address(0) as caddress to make the call succeed (no code execution)
        address caddress = address(0);
        address[] memory tos = new address[](0);
        uint v = 100;

        // Try transfer on reference
        bool okRef;
        try c.transfer(from, caddress, tos, v) {
            okRef = true;
        } catch {
            okRef = false;
        }
        // Reference reverts because of require before loop, so okRef is false
        assertTrue(!okRef, "Reference should revert");

        // Deploy a separate buggy version to test
        // We cannot use the same contract instance; we need a buggy one.
        // But the test expects a single c instance. So we'll test the bug by deploying a new contract with the mutant code.
        // Actually we must use the same C contract but the bug is in that contract. Let's assume we test the buggy version separately.
        // To keep consistent with the spec: the test runs on the reference C, so we need to compare behavior.
        // The prompt says "PASSES on the reference C and FAILS on the buggy version" - so we can have two contracts.
        // Let's redeploy with a buggy version. 
        // I'll deploy a separate buggy contract C_bug (not allowed to define new contract). 
        // To comply, we can deploy a new instance of C but that is the reference; we cannot get the buggy one without redefining.
        // Alternative: use a single test that calls transfer on the reference (which reverts) and assert it reverts.
        // But the buggy version would not revert, so the test fails on buggy version. This is the standard approach.
        // The prompt wants a single test that passes on reference and fails on buggy - we can do that by just testing the reference's behavior.
        // The test reads: if we run it on reference, it passes (okRef is false, assertTrue(!okRef) passes).
        // On buggy, okRef would be true, assertTrue(!okRef) fails. So this works.
    }
}
